/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        const pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        scwin.dateSetting();
        $('input[name=ipt_isurNm1]').keypress(async function(e) {
                if (e.keyCode == 13) {
                    await scwin.search('1');
                }
        });
        $('input[name=searchRadio]').bind("click", function() {
                $c.util.getComponent('ipt_curSh').setValue($(this).val());
                $('.paging').empty();
                const resetPaging = "<tr><td style='padding-left:5px'><img diabled src='/img/btn/btn-pprev.gif' alt=''></td><td style='padding-left:5px'><img src='/img/btn/btn-prev.gif' alt='' ></td><td class='bg_pagingbar'></td><td>1</td><td style='padding-left:5px'><img src='/img/btn/btn-next.gif' border='0' ></td><td style='padding-left:5px'><img src='/img/btn/btn-nnext.gif' alt='' ></a></td></tr>";
                $('.paging').append(resetPaging);
        });
        $c.util.getComponent("ipt_isurNm1").focus();
        const gubunRadio = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubunRadio" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubunRadio"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubunRadio" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubunRadio")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubunRadio" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubunRadio"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubunRadio" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubunRadio")))));
        if (gubunRadio === '') {
            scwin.appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 12);
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000.onpageload' }); }
};

/**
 * @method
 * @name scwin.init_loadList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
